package com.edgecloud.alert.service;
import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*; import java.util.*; import org.junit.jupiter.api.*; import com.edgecloud.alert.client.*; import com.edgecloud.alert.exception.ProjectAccessDeniedException; import com.edgecloud.alert.security.EdgeCloudJwtAuthenticationToken;
class EscalationAuthorizationTest {private ProjectAccessClient client=mock(ProjectAccessClient.class);private AlertRuleAuthorizationService service=new AlertRuleAuthorizationService(client);private UUID project=UUID.randomUUID();
 @Test void onlyProjectAdminOrPlatformAdminMayModifyPolicy(){for(String role:List.of("VIEWER","OPERATOR")){var token=token(role);when(client.getWorkspace(project,"jwt")).thenReturn(workspace(role));assertThatThrownBy(()->service.requireAdminMutation(project,token)).isInstanceOf(ProjectAccessDeniedException.class);}var projectAdmin=token("PROJECT_ADMIN");when(client.getWorkspace(project,"jwt")).thenReturn(workspace("PROJECT_ADMIN"));assertThatCode(()->service.requireAdminMutation(project,projectAdmin)).doesNotThrowAnyException();var admin=token("ADMIN");when(client.getWorkspace(project,"jwt")).thenReturn(workspace("VIEWER"));assertThatCode(()->service.requireAdminMutation(project,admin)).doesNotThrowAnyException();}
 private EdgeCloudJwtAuthenticationToken token(String role){return new EdgeCloudJwtAuthenticationToken(UUID.randomUUID(),role,"jwt");}private ProjectWorkspaceResponse workspace(String role){return new ProjectWorkspaceResponse(project,"P","ACTIVE",UUID.randomUUID(),role,List.of(),List.of());}
}
